const std = @import("std");
pub var allocator: std.mem.Allocator = undefined;
pub var backing: std.mem.Allocator = undefined;
pub var scratch: std.mem.Allocator = undefined;
pub const Strings = []const []const u8;
pub const Color = [4]i64;
pub const RGB = [3]i64;
pub fn alloc(comptime T: type, count: usize) []T { return allocator.alloc(T, count) catch @panic("allocation failed"); }
pub fn tempAlloc(comptime T: type, count: usize) []T { return scratch.alloc(T, count) catch @panic("allocation failed"); }
pub fn create(comptime T: type, value: T) *T { const result = allocator.create(T) catch @panic("allocation failed"); result.* = value; return result; }
pub fn append(comptime T: type, list: *std.ArrayList(T), value: T) void { list.append(allocator, value) catch @panic("allocation failed"); }
pub fn push(comptime T: type, list: *std.ArrayList(T), value: T) void { list.append(scratch, value) catch @panic("allocation failed"); }
pub fn fmt(comptime pattern: []const u8, args: anytype) []const u8 { return std.fmt.allocPrint(allocator, pattern, args) catch @panic("allocation failed"); }
pub fn eq(a: []const u8, b: []const u8) bool { return std.mem.eql(u8, a, b); }
pub fn int(value: anytype) i64 { return @intCast(value); }
pub fn index(value: i64) usize { return @intCast(value); }
pub fn abs(value: i64) i64 { return if (value < 0) -value else value; }
pub fn number(text: []const u8) i64 { return std.fmt.parseInt(i64, text, 10) catch unreachable; }
pub fn split(text: []const u8, delimiter: u8) Strings { var result: std.ArrayList([]const u8) = .empty; var it = std.mem.splitScalar(u8, text, delimiter); while (it.next()) |part| append([]const u8, &result, part); return result.items; }
pub fn words(text: []const u8) Strings { var result: std.ArrayList([]const u8) = .empty; var it = std.mem.tokenizeScalar(u8, text, ' '); while (it.next()) |part| append([]const u8, &result, part); return result.items; }
pub fn lines(text: []const u8) Strings { const result = split(text, '\n'); return result[0..result.len - 1]; }
pub fn join(parts: Strings, separator: []const u8) []const u8 { return std.mem.join(allocator, separator, parts) catch @panic("allocation failed"); }
pub const Text = struct {
    data: std.ArrayList(u8) = .empty,
    pub fn write(self: *Text, text: []const u8) void { self.data.appendSlice(allocator, text) catch @panic("allocation failed"); }
    pub fn byte(self: *Text, ch: u8) void { append(u8, &self.data, ch); }
    pub fn add(self: *Text, comptime pattern: []const u8, args: anytype) void { self.write(fmt(pattern, args)); }
    pub fn value(self: Text) []const u8 { return self.data.items; }
};
pub const Lines = struct {
    data: std.ArrayList([]const u8) = .empty,
    pub fn write(self: *Lines, text: []const u8) void { append([]const u8, &self.data, text); }
    pub fn add(self: *Lines, comptime pattern: []const u8, args: anytype) void { self.write(fmt(pattern, args)); }
    pub fn content(self: Lines) []const u8 { var text: Text = .{}; for (self.data.items) |line| { text.write(line); text.byte('\n'); } return text.value(); }
};
pub const Point = struct { x: i64, y: i64 };
pub const Segment = struct { first: Point, last: Point };
pub const Rect = struct {
    x0: i64, y0: i64, x1: i64, y1: i64,
    pub fn empty(self: Rect) bool { return self.x0 > self.x1 or self.y0 > self.y1; }
    pub fn contains(self: Rect, point: Point) bool { return point.x >= self.x0 and point.x <= self.x1 and point.y >= self.y0 and point.y <= self.y1; }
    pub fn intersect(self: Rect, other: Rect) Rect { return .{ .x0 = @max(self.x0, other.x0), .y0 = @max(self.y0, other.y0), .x1 = @min(self.x1, other.x1), .y1 = @min(self.y1, other.y1) }; }
};
pub fn boxText(box: ?Rect) []const u8 { const rect = box orelse return "none"; return fmt("{d} {d} {d} {d}", .{ rect.x0, rect.y0, rect.x1, rect.y1 }); }
pub const Mask = struct {
    width: usize, height: usize, bits: []bool,
    pub fn init(width: usize, height: usize) Mask { const bits = tempAlloc(bool, width * height); @memset(bits, false); return .{ .width = width, .height = height, .bits = bits }; }
    pub fn add(self: Mask, point: Point, clip: Rect) void { if (clip.contains(point)) self.bits[index(point.y) * self.width + index(point.x)] = true; }
    pub fn count(self: Mask) usize { var result: usize = 0; for (self.bits) |value| { if (value) result += 1; } return result; }
    pub fn box(self: Mask) ?Rect { var result: ?Rect = null; for (self.bits, 0..) |value, i| { if (!value) continue; const x = int(i % self.width); const y = int(i / self.width); if (result) |*rect| { rect.x0 = @min(rect.x0, x); rect.y0 = @min(rect.y0, y); rect.x1 = @max(rect.x1, x); rect.y1 = @max(rect.y1, y); } else result = .{ .x0 = x, .y0 = y, .x1 = x, .y1 = y }; } return result; }
};
pub fn roundRatio(numerator: i64, denominator: i64) i64 { const n = if (denominator < 0) -numerator else numerator; const d = abs(denominator); return @divFloor(2 * n + d, 2 * d); }
pub fn effectiveAlpha(alpha: i64, opacity: i64) i64 { return roundRatio(alpha * opacity, 255); }
pub const Mode = enum { normal, multiply, screen };
pub const Rule = enum { evenodd, nonzero };
pub const Layer = struct {
    width: usize, height: usize, opacity: i64, mode: Mode, colors: []?Color, lines: []usize,
    pub fn init(width: usize, height: usize, opacity: i64, mode: Mode) Layer { const colors = alloc(?Color, width * height); @memset(colors, null); const origins = alloc(usize, width * height); @memset(origins, 0); return .{ .width = width, .height = height, .opacity = opacity, .mode = mode, .colors = colors, .lines = origins }; }
    pub fn alpha(self: *const Layer, pixel: usize) i64 { const color = self.colors[pixel] orelse return 0; return effectiveAlpha(color[3], self.opacity); }
    pub fn paint(self: *Layer, pixel: usize, color: Color, line: usize) void { self.colors[pixel] = color; self.lines[pixel] = line; }
};
fn blend(mode: Mode, source: i64, value: i64) i64 { return switch (mode) { .normal => source, .multiply => roundRatio(source * value, 255), .screen => 255 - roundRatio((255 - source) * (255 - value), 255) }; }
pub fn composite(layers: []const *Layer, background: Color, width: usize, height: usize) []const RGB { const image = alloc(RGB, width * height); for (image, 0..) |*rgb, pixel| { rgb.* = .{ background[0], background[1], background[2] }; for (layers) |layer| { const color = layer.colors[pixel] orelse continue; const alpha = effectiveAlpha(color[3], layer.opacity); for (0..3) |channel| rgb[channel] = roundRatio(alpha * blend(layer.mode, color[channel], rgb[channel]) + (255 - alpha) * rgb[channel], 255); } } return image; }

const std = @import("std");
const C = @import("canvas.zig");
fn code(point: C.Point, clip: C.Rect) u4 { var result: u4 = 0; if (point.x < clip.x0) result |= 1; if (point.x > clip.x1) result |= 2; if (point.y < clip.y0) result |= 4; if (point.y > clip.y1) result |= 8; return result; }
pub fn segment(input: C.Segment, clip: C.Rect) ?C.Segment { var result = input; while (true) { const first_code = code(result.first, clip); const last_code = code(result.last, clip); if (first_code == 0 and last_code == 0) return result; if (first_code & last_code != 0) return null; const outside_code = if (first_code != 0) first_code else last_code; const a = if (first_code != 0) result.first else result.last; const b = if (first_code != 0) result.last else result.first; var point: C.Point = undefined;
        if (outside_code & 4 != 0) point = .{ .x = a.x + C.roundRatio((b.x - a.x) * (clip.y0 - a.y), b.y - a.y), .y = clip.y0 } else if (outside_code & 8 != 0) point = .{ .x = a.x + C.roundRatio((b.x - a.x) * (clip.y1 - a.y), b.y - a.y), .y = clip.y1 } else if (outside_code & 2 != 0) point = .{ .x = clip.x1, .y = a.y + C.roundRatio((b.y - a.y) * (clip.x1 - a.x), b.x - a.x) } else point = .{ .x = clip.x0, .y = a.y + C.roundRatio((b.y - a.y) * (clip.x0 - a.x), b.x - a.x) };
        if (first_code != 0) result.first = point else result.last = point;
    } }
fn inside(point: C.Point, axis: usize, limit: i64, minimum: bool) bool { const value = if (axis == 0) point.x else point.y; return if (minimum) value >= limit else value <= limit; }
fn intersection(a: C.Point, b: C.Point, axis: usize, limit: i64) C.Point { return if (axis == 0) .{ .x = limit, .y = a.y + C.roundRatio((limit - a.x) * (b.y - a.y), b.x - a.x) } else .{ .x = a.x + C.roundRatio((limit - a.y) * (b.x - a.x), b.y - a.y), .y = limit }; }
pub fn polygon(input: []const C.Point, clip: C.Rect) []const C.Point { const Boundary = struct { axis: usize, limit: i64, minimum: bool }; const boundaries = [_]Boundary{ .{ .axis = 0, .limit = clip.x0, .minimum = true }, .{ .axis = 0, .limit = clip.x1 + 1, .minimum = false }, .{ .axis = 1, .limit = clip.y0, .minimum = true }, .{ .axis = 1, .limit = clip.y1 + 1, .minimum = false } }; var vertices = input;
    for (boundaries) |boundary| { var output: std.ArrayList(C.Point) = .empty; for (vertices, 0..) |last, i| { const first = vertices[if (i == 0) vertices.len - 1 else i - 1]; const last_inside = inside(last, boundary.axis, boundary.limit, boundary.minimum); const first_inside = inside(first, boundary.axis, boundary.limit, boundary.minimum); if (last_inside) { if (!first_inside) C.push(C.Point, &output, intersection(first, last, boundary.axis, boundary.limit)); C.push(C.Point, &output, last); } else if (first_inside) C.push(C.Point, &output, intersection(first, last, boundary.axis, boundary.limit)); } vertices = output.items; } return vertices;
}

const std = @import("std");
const C = @import("canvas.zig");
const Crossing = struct { start: i64, direction: i64 };
fn less(_: void, a: Crossing, b: Crossing) bool { return if (a.start == b.start) a.direction < b.direction else a.start < b.start; }
fn crossingStart(a: C.Point, b: C.Point, y: i64) i64 { var denominator = b.y - a.y; var numerator = 2 * a.x * denominator + (2 * y + 1 - 2 * a.y) * (b.x - a.x); if (denominator < 0) { numerator = -numerator; denominator = -denominator; } return @divFloor(numerator - denominator, 2 * denominator) + 1; }
pub fn polygons(mask: C.Mask, sequences: []const []const C.Point, rule: C.Rule, clip: C.Rect) void { var edges: std.ArrayList(C.Segment) = .empty; for (sequences) |vertices| { for (vertices, 0..) |first, i| { const last = vertices[(i + 1) % vertices.len]; if (first.y != last.y) C.push(C.Segment, &edges, .{ .first = first, .last = last }); } } var y = clip.y0;
    while (y <= clip.y1) : (y += 1) { var crossings: std.ArrayList(Crossing) = .empty; for (edges.items) |edge| { if (@min(edge.first.y, edge.last.y) <= y and y < @max(edge.first.y, edge.last.y)) C.push(Crossing, &crossings, .{ .start = crossingStart(edge.first, edge.last, y), .direction = if (edge.last.y > edge.first.y) 1 else -1 }); } std.mem.sort(Crossing, crossings.items, {}, less); var count: usize = 0; var winding: i64 = 0; var index: usize = 0; var x = clip.x0;
        while (x <= clip.x1) : (x += 1) { while (index < crossings.items.len and crossings.items[index].start <= x) : (index += 1) { count += 1; winding += crossings.items[index].direction; } if (if (rule == .evenodd) count % 2 == 1 else winding != 0) mask.add(.{ .x = x, .y = y }, clip); }
    }
}
pub fn shape(mask: C.Mask, center: C.Point, points: []const C.Point, clip: C.Rect) void { var extents = [_]i64{-1} ** 201; for (points) |point| { const i = C.index(point.y + 100); extents[i] = @max(extents[i], C.abs(point.x)); } for (extents, 0..) |extent, i| { if (extent < 0) continue; const y = center.y + C.int(i) - 100; if (y < clip.y0 or y > clip.y1) continue; var x = @max(clip.x0, center.x - extent); const end = @min(clip.x1, center.x + extent); while (x <= end) : (x += 1) mask.add(.{ .x = x, .y = y }, clip); } }
fn sameColor(a: ?C.Color, b: ?C.Color) bool { if (a == null or b == null) return a == null and b == null; return std.mem.eql(i64, &a.?, &b.?); }
pub fn flood(mask: C.Mask, layer: *const C.Layer, seed: C.Point, clip: C.Rect) void { const target = layer.colors[C.index(seed.y) * mask.width + C.index(seed.x)]; var pending: std.ArrayList(C.Point) = .empty; mask.add(seed, clip); C.push(C.Point, &pending, seed); while (pending.pop()) |point| { const neighbors = [_]C.Point{ .{ .x = point.x + 1, .y = point.y }, .{ .x = point.x - 1, .y = point.y }, .{ .x = point.x, .y = point.y + 1 }, .{ .x = point.x, .y = point.y - 1 } }; for (neighbors) |next| { if (!clip.contains(next)) continue; const pixel = C.index(next.y) * mask.width + C.index(next.x); if (!mask.bits[pixel] and sameColor(layer.colors[pixel], target)) { mask.bits[pixel] = true; C.push(C.Point, &pending, next); } } } }

const std = @import("std");
const C = @import("canvas.zig");
const P = @import("primitives.zig");
const F = @import("fill.zig");
const K = @import("clipping.zig");
const W = @import("ppm_writer.zig");
const Tag = enum { LINE, RECT, FILLRECT, CIRCLE, FILLCIRCLE, ELLIPSE, FILLELLIPSE, POLYLINE, POLYGON, FILLPOLYGON, PATH, FILLPATH, FLOOD, TEXT, ERASE, TRANSLATE, SCALE, ROTATE, SAVE, RESTORE, CLIP, NOCLIP, USE };
const ErrorName = enum { unknown_command, bad_arguments, unknown_style, unknown_symbol, unknown_glyph, bad_value, stack_empty };
const Pen = struct { width: i64, color: []const u8, on: i64, off: i64 };
const Axis = enum { x, y };
const Brush = struct { colors: C.Strings, axis: ?Axis, rule: C.Rule };
const Styles = struct { colors: std.StringHashMapUnmanaged(C.Color) = .empty, pens: std.StringHashMapUnmanaged(Pen) = .empty, brushes: std.StringHashMapUnmanaged(Brush) = .empty };
const Font = struct { width: i64, height: i64, glyphs: std.AutoHashMapUnmanaged(u8, []const C.Point) = .empty };
const Command = struct { line: usize, keyword: []const u8, args: C.Strings };
const Item = union(enum) { command: *Command, repetition: *Repetition };
const Repetition = struct { count: usize, dx: i64, dy: i64, body: std.ArrayList(Item) = .empty };
const Block = struct { name: []const u8, opacity: i64 = 0, mode: C.Mode = .normal, body: std.ArrayList(Item) = .empty, end_line: usize = 0 };
const Scene = struct { width: usize = 0, height: usize = 0, background: []const u8 = "", layers: std.ArrayList(*Block) = .empty, symbols: std.StringHashMapUnmanaged(*Block) = .empty };
const Probe = struct { point: bool, values: []const i64 };
const PathCommand = struct { letter: u8, values: [6]i64 = [_]i64{0} ** 6, count: usize };
const Subpath = struct { points: std.ArrayList(C.Point) = .empty, closed: bool = false };
const Execution = struct { sequence: usize, layer: usize, command: *const Command, kind: enum { drawing, state, failed } = .state, failure: ?ErrorName = null, pixels: usize = 0, box: ?C.Rect = null };
const Pair = struct { matrix: [6]i64, clip: C.Rect };
const Snapshot = struct { matrix: [6]i64, clip: C.Rect, stack: []const Pair };
const State = struct {
    matrix: [6]i64 = .{ 1, 0, 0, 1, 0, 0 }, clip: C.Rect, stack: std.ArrayList(Pair) = .empty,
    fn snapshot(self: *const State) Snapshot { return .{ .matrix = self.matrix, .clip = self.clip, .stack = C.backing.dupe(Pair, self.stack.items) catch @panic("allocation failed") }; }
    fn rollback(self: *State, saved: Snapshot) void { self.matrix = saved.matrix; self.clip = saved.clip; self.stack.items.len = 0; self.stack.appendSlice(C.allocator, saved.stack) catch @panic("allocation failed"); }
    fn point(self: *const State, x: i64, y: i64) C.Point { const m = self.matrix; return .{ .x = m[0] * x + m[1] * y + m[4], .y = m[2] * x + m[3] * y + m[5] }; }
    fn rectangle(self: *const State, values: []const i64) C.Rect { const first = self.point(values[0], values[1]); const last = self.point(values[2], values[3]); return .{ .x0 = @min(first.x, last.x), .y0 = @min(first.y, last.y), .x1 = @max(first.x, last.x), .y1 = @max(first.y, last.y) }; }
    fn radii(self: *const State, rx: i64, ry: i64) C.Point { const m = self.matrix; return .{ .x = C.abs(m[0]) * rx + C.abs(m[1]) * ry, .y = C.abs(m[2]) * rx + C.abs(m[3]) * ry }; }
    fn translate(self: *State, dx: i64, dy: i64) void { self.matrix[4] += self.matrix[0] * dx + self.matrix[1] * dy; self.matrix[5] += self.matrix[2] * dx + self.matrix[3] * dy; }
};
fn enumValue(comptime T: type, name: []const u8) ?T { inline for (@typeInfo(T).@"enum".field_names) |candidate| { if (C.eq(candidate, name)) return @field(T, candidate); } return null; }
fn upper(ch: u8) u8 { return if (ch >= 'a' and ch <= 'z') ch - 32 else ch; }
fn integer(word: []const u8) bool { if (word.len == 0) return false; const digits = if (word[0] == '-') word[1..] else word; if (digits.len == 0) return false; for (digits) |ch| { if (ch < '0' or ch > '9') return false; } return true; }
fn allIntegers(words: C.Strings) bool { for (words) |word| { if (!integer(word)) return false; } return true; }
fn numbers(words: C.Strings) []const i64 { const result = C.tempAlloc(i64, words.len); for (words, result) |word, *value| value.* = C.number(word); return result; }
fn permanentNumbers(words: C.Strings) []const i64 { const result = C.alloc(i64, words.len); for (words, result) |word, *value| value.* = C.number(word); return result; }
fn penCommand(tag: Tag) bool { return switch (tag) { .LINE, .RECT, .CIRCLE, .ELLIPSE, .POLYLINE, .POLYGON, .PATH => true, else => false }; }
fn brushCommand(tag: Tag) bool { return switch (tag) { .FILLRECT, .FILLCIRCLE, .FILLELLIPSE, .FILLPOLYGON, .FILLPATH, .FLOOD, .TEXT => true, else => false }; }
fn stateCommand(tag: Tag) bool { return @intFromEnum(tag) >= @intFromEnum(Tag.TRANSLATE); }
fn arity(letter: u8) ?usize { return switch (upper(letter)) { 'M', 'L' => 2, 'H', 'V' => 1, 'Q' => 4, 'C' => 6, 'Z' => 0, else => null }; }
fn parsePath(words: C.Strings) ?[]const PathCommand { var result: std.ArrayList(PathCommand) = .empty; var index: usize = 0; var starts = true; while (index < words.len) { if (words[index].len != 1) return null; const letter = words[index][0]; const count = arity(letter) orelse return null; if (index + count >= words.len or !allIntegers(words[index + 1..index + 1 + count])) return null; if (starts and upper(letter) != 'M') return null; var command: PathCommand = .{ .letter = letter, .count = count }; for (words[index + 1..index + 1 + count], 0..) |word, i| command.values[i] = C.number(word); C.push(PathCommand, &result, command); starts = upper(letter) == 'Z'; index += count + 1; } return if (result.items.len == 0) null else result.items; }
fn validForm(tag: Tag, args: C.Strings) bool { const Form = struct { count: usize, first_integer: usize }; const fixed: ?Form = switch (tag) { .LINE, .RECT, .FILLRECT, .ELLIPSE, .FILLELLIPSE => .{ .count = 5, .first_integer = 1 }, .CIRCLE, .FILLCIRCLE => .{ .count = 4, .first_integer = 1 }, .FLOOD, .USE => .{ .count = 3, .first_integer = 1 }, .ERASE, .CLIP => .{ .count = 4, .first_integer = 0 }, .TRANSLATE, .SCALE => .{ .count = 2, .first_integer = 0 }, .ROTATE => .{ .count = 1, .first_integer = 0 }, .SAVE, .RESTORE, .NOCLIP => .{ .count = 0, .first_integer = 0 }, else => null };
    if (fixed) |form| return args.len == form.count and allIntegers(args[form.first_integer..]); if (tag == .TEXT) return args.len == 5 and allIntegers(args[1..3]); if (tag == .POLYLINE or tag == .POLYGON or tag == .FILLPOLYGON) return args.len >= 2 and allIntegers(args[1..]) and C.int(args.len) == 2 + 2 * C.number(args[1]); return args.len >= 2 and integer(args[1]) and parsePath(args[2..]) != null;
}
fn readStyles(text: []const u8) Styles { var result: Styles = .{}; for (C.lines(text)) |line| { if (line.len == 0 or line[0] == '#') continue; const words = C.words(line); const name = words[1]; if (C.eq(words[0], "color")) { var color: C.Color = undefined; for (words[2..], &color) |word, *value| value.* = C.number(word); result.colors.put(C.allocator, name, color) catch @panic("allocation failed"); } else if (C.eq(words[0], "pen")) { result.pens.put(C.allocator, name, .{ .width = C.number(words[2]), .color = words[3], .on = C.number(words[4]), .off = C.number(words[5]) }) catch @panic("allocation failed"); } else { const solid = C.eq(words[0], "brush"); result.brushes.put(C.allocator, name, .{ .colors = words[2..if (solid) 3 else 4], .axis = if (solid) null else enumValue(Axis, words[4]).?, .rule = enumValue(C.Rule, words[if (solid) 3 else 5]).? }) catch @panic("allocation failed"); } } return result; }
fn readFont(text: []const u8) Font { const lines = C.lines(text); const header = C.words(lines[0]); var font: Font = .{ .width = C.number(header[1]), .height = C.number(header[2]) }; var index: usize = 1; while (index < lines.len) { const ch = C.words(lines[index])[1][0]; var dots: std.ArrayList(C.Point) = .empty; for (0..C.index(font.height)) |row| { for (lines[index + row + 1], 0..) |mark, column| { if (mark == '#') C.append(C.Point, &dots, .{ .x = C.int(column), .y = C.int(row) }); } } font.glyphs.put(C.allocator, ch, dots.items) catch @panic("allocation failed"); index += C.index(font.height) + 1; } return font; }
