}
fn probeLines(probes: []const Probe, renderer: *const Renderer, image: []const C.RGB) C.Lines { var result: C.Lines = .{}; const width = renderer.scene.width; const layers = renderer.layers.items;
    for (probes, 1..) |probe, number| { const values = probe.values; if (probe.point) { const x = values[0]; const y = values[1]; const pixel = C.index(y) * width + C.index(x); var stack: std.ArrayList([]const u8) = .empty; for (layers, 1..) |layer, i| { if (layer.alpha(pixel) > 0) C.append([]const u8, &stack, C.fmt("{d}:{d}", .{ i, layer.lines[pixel] })); } const color = image[pixel]; result.add("point {d} {d} {d} rgb {d} {d} {d} layers {d} stack {s}", .{ number, x, y, color[0], color[1], color[2], stack.items.len, if (stack.items.len == 0) "none" else C.join(stack.items, " ") }); } else {
