pub fn ppm(image: []const C.RGB, width: usize, height: usize) C.Lines { var result: C.Lines = .{}; result.write("P3"); result.add("{d} {d}", .{ width, height }); result.write("255"); for (0..height) |y| { var text: C.Text = .{}; for (image[y * width..(y + 1) * width], 0..) |color, x| { if (x > 0) text.byte(' '); text.add("{d} {d} {d}", .{ color[0], color[1], color[2] }); } result.write(text.value()); } return result; }
pub fn preview(image: []const C.RGB, width: usize, height: usize) C.Lines { const ramp = "@%#*+=-:,."; var result: C.Lines = .{}; var top: usize = 0; while (top < height) : (top += 4) { var text: C.Text = .{}; var left: usize = 0; while (left < width) : (left += 2) { var total: i64 = 0; for (top..top + 4) |y| { for (left..left + 2) |x| { const color = image[y * width + x]; total += 299 * color[0] + 587 * color[1] + 114 * color[2]; } } const lum = @divFloor(total, 8000); text.byte(ramp[C.index(@divFloor(lum * 10, 256))]); } result.write(text.value()); } return result; }

