pub fn bresenham(first: C.Point, last: C.Point) []const C.Point {
    var x = first.x; var y = first.y; const dx = C.abs(last.x - x); const dy = -C.abs(last.y - y); const sx: i64 = if (x < last.x) 1 else -1; const sy: i64 = if (y < last.y) 1 else -1; var error_value = dx + dy; var result: std.ArrayList(C.Point) = .empty;
    while (true) { C.push(C.Point, &result, .{ .x = x, .y = y }); if (x == last.x and y == last.y) return result.items; const doubled = 2 * error_value; if (doubled >= dy) { error_value += dy; x += sx; } if (doubled <= dx) { error_value += dx; y += sy; } }
}
pub fn expand(mask: C.Mask, point: C.Point, width: i64, clip: C.Rect) void { const low = -@divFloor(width - 1, 2); var dy = low; while (dy < low + width) : (dy += 1) { var dx = low; while (dx < low + width) : (dx += 1) mask.add(.{ .x = point.x + dx, .y = point.y + dy }, clip); } }
